.sl-gallery-scrapbook { padding-block: clamp(3rem, 6vw, 5rem); padding-inline: clamp(1rem, 3vw, 2rem); background-color: var(--smartlearn-bg); font-family: var(--smartlearn-body-font, system-ui, sans-serif); }
.sl-gallery-scrapbook .sl-container { max-width: 1200px; width: 100%; margin-inline: auto; }
.sl-gallery-scrapbook .sl-scrapbook-header { text-align: center; margin-bottom: clamp(2.5rem, 5vw, 3.5rem); }
.sl-gallery-scrapbook .sl-section-title { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.75rem, 3.5vw, 2.25rem); font-weight: 700; color: var(--smartlearn-text); margin: 0 0 0.5rem; }
.sl-gallery-scrapbook .sl-section-subtitle { font-size: 1.125rem; color: var(--smartlearn-text-muted); margin: 0; }
.sl-gallery-scrapbook .sl-scrapbook-grid { display: grid; grid-template-columns: 1fr; grid-template-areas: "large" "quote" "tall" "wide"; gap: 1.25rem; }
.sl-gallery-scrapbook .sl-scrapbook-item { position: relative; border-radius: var(--smartlearn-radius, 0.75rem); overflow: hidden; background-color: var(--smartlearn-card-bg); box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08); transition: transform 0.25s ease; }
.sl-gallery-scrapbook .sl-sb-large { grid-area: large; aspect-ratio: 4/3; }
.sl-gallery-scrapbook .sl-sb-quote { grid-area: quote; display: flex; align-items: center; justify-content: center; padding: clamp(1.5rem, 3vw, 2rem); background-color: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); }
.sl-gallery-scrapbook .sl-sb-tall { grid-area: tall; aspect-ratio: 4/3; }
.sl-gallery-scrapbook .sl-sb-wide { grid-area: wide; aspect-ratio: 4/3; }
.sl-gallery-scrapbook .sl-scrapbook-item img { width: 100%; height: 100%; object-fit: cover; display: block; }
.sl-gallery-scrapbook .sl-sb-caption { position: absolute; bottom: 0; inset-inline: 0; background: linear-gradient(to top, rgba(0, 0, 0, 0.82), transparent); color: #ffffff; padding: 2rem 1rem 1rem; font-weight: 600; font-size: 1rem; }
.sl-gallery-scrapbook .sl-video-item.is-playing .sl-sb-caption { display: none; }
.sl-gallery-scrapbook .sl-sb-quote-text { font-family: var(--smartlearn-heading-font, inherit); font-size: clamp(1.2rem, 2.5vw, 1.45rem); font-weight: 700; line-height: 1.4; font-style: italic; margin: 0; text-align: center; }
.sl-gallery-scrapbook .sl-play-overlay { position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 64px; height: 64px; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); border: none; border-radius: 50%; display: flex; align-items: center; justify-content: center; box-shadow: 0 10px 25px rgba(0, 0, 0, 0.25); cursor: pointer; transition: transform 0.2s ease, background-color 0.2s ease; z-index: 5; }
.sl-gallery-scrapbook .sl-play-overlay:hover { background: var(--smartlearn-btn-hover-bg, var(--smartlearn-btn-bg)); transform: translate(-50%, -50%) scale(1.08); }
.sl-gallery-scrapbook .sl-play-overlay:focus-visible, .sl-gallery-scrapbook .sl-close-video:focus-visible { outline: 3px solid var(--smartlearn-primary); outline-offset: 2px; }
.sl-gallery-scrapbook .sl-close-video { position: absolute; top: 0.75rem; inset-inline-end: 0.75rem; z-index: 20; width: 44px; height: 44px; border-radius: 50%; border: none; background: var(--smartlearn-btn-bg, var(--smartlearn-primary)); color: var(--smartlearn-btn-text); font-size: 1.35rem; line-height: 1; cursor: pointer; display: flex; align-items: center; justify-content: center; }
@media (min-width: 768px) {
  .sl-gallery-scrapbook .sl-scrapbook-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); grid-auto-rows: 220px; grid-template-areas: "large large quote quote" "large large tall tall" "wide wide tall tall"; gap: 1.5rem; }
  .sl-gallery-scrapbook .sl-sb-large, .sl-gallery-scrapbook .sl-sb-tall, .sl-gallery-scrapbook .sl-sb-wide { aspect-ratio: auto; height: 100%; }
}
@media (prefers-reduced-motion: no-preference) { .sl-gallery-scrapbook .sl-scrapbook-item:hover { transform: scale(1.015); z-index: 5; } }
@media (prefers-reduced-motion: reduce) { .sl-gallery-scrapbook .sl-scrapbook-item, .sl-gallery-scrapbook .sl-play-overlay { transition: none; } }

